#!/bin/sh
# Generated by FWShift: AWS EC2 security groups for one VPC, created with the AWS CLI. Read the report first:
# what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                 prints the calls, makes none (no AWS access needed)
#   VPC_ID=vpc-... CHECK=1 sh THIS_FILE    sends every call with --dry-run: AWS checks the permissions
#   VPC_ID=vpc-... sh THIS_FILE            creates the groups and their rules
#
# AWS_OPTS adds options to every call, for example AWS_OPTS='--region eu-west-1 --profile prod'.
#
# The groups are created WITHOUT members: nothing changes for any traffic until they are attached. Attach each
# group to the network interfaces whose private addresses are listed after it (# attach ...): an interface gets
# every group whose list holds one of its addresses, and then no other groups. A group of the same name in the
# VPC stops the script before anything is created; a call AWS refuses stops it where it is (delete the groups
# it made with aws ec2 delete-security-group --group-id ... and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
CHECK="${CHECK:-}"
AWS_OPTS="${AWS_OPTS:-}"
if [ -z "$DRY_RUN" ]; then
  : "${VPC_ID:?set VPC_ID to the id of the VPC (vpc-...), or DRY_RUN=1 to print the calls}"
else
  VPC_ID="${VPC_ID:-vpc-DRYRUN}"
fi
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
show() { printf 'aws ec2' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; }
# change CALL ARGS...: a call that changes something
change() {
  if [ -n "$DRY_RUN" ]; then show "$@"; return 0; fi
  if [ -n "$CHECK" ]; then
    out=$(aws ec2 "$@" --dry-run $AWS_OPTS 2>&1)
    case "$out" in *DryRunOperation*) printf 'checked: %s\n' "$1" >&2; return 0 ;; esac
    fail "aws ec2 $1: $out"
  fi
  aws ec2 "$@" $AWS_OPTS >/dev/null || fail "aws ec2 $1"
}
# free NAME: stops the script when the VPC has a group of that name
free() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  found=$(aws ec2 describe-security-groups --filters "Name=vpc-id,Values=$VPC_ID" "Name=group-name,Values=$1" --query 'SecurityGroups[0].GroupId' --output text $AWS_OPTS) || fail "describe-security-groups: $found"
  [ "$found" = None ] || fail "a group named $1 exists in $VPC_ID already ($found); nothing was created"
}
# revoke GROUP PERMISSIONS: takes an outbound rule off a new group; a rule that is not there is fine
revoke() {
  out=$(aws ec2 revoke-security-group-egress --group-id "$1" --ip-permissions "$2" $AWS_OPTS 2>&1) && return 0
  case "$out" in *InvalidPermission.NotFound*|*InvalidParameterValue*) return 0 ;; esac
  fail "revoke-security-group-egress $1: $out"
}
# group NAME DESCRIPTION: creates a group without rules and prints its id
group() {
  if [ -n "$DRY_RUN" ]; then show create-security-group --group-name "$1" --description "$2" --vpc-id "$VPC_ID"; printf 'sg-dryrun-%s\n' "$1"; return 0; fi
  if [ -n "$CHECK" ]; then change create-security-group --group-name "$1" --description "$2" --vpc-id "$VPC_ID"; printf '%s\n' "$STAND_IN"; return 0; fi
  id=$(aws ec2 create-security-group --group-name "$1" --description "$2" --vpc-id "$VPC_ID" --tag-specifications '[{"ResourceType":"security-group","Tags":[{"Key":"fwshift","Value":"generated"}]}]' --query GroupId --output text $AWS_OPTS) || fail "create-security-group $1"
  aws ec2 wait security-group-exists --group-ids "$id" $AWS_OPTS || fail "group $id did not appear"
  # A new group allows everything outbound (IPv4, and IPv6 where the VPC has it): take that off, and make sure.
  revoke "$id" '[{"IpProtocol":"-1","IpRanges":[{"CidrIp":"0.0.0.0/0"}]}]'
  revoke "$id" '[{"IpProtocol":"-1","Ipv6Ranges":[{"CidrIpv6":"::/0"}]}]'
  left=$(aws ec2 describe-security-group-rules --filters "Name=group-id,Values=$id" --query 'length(SecurityGroupRules[?IsEgress])' --output text $AWS_OPTS) || fail "describe-security-group-rules $id"
  [ "$left" = 0 ] || fail "group $id still has $left outbound rules; it was not given any others"
  printf 'created %s %s\n' "$1" "$id" >&2
  printf '%s\n' "$id"
}
ingress() { perms=$(cat); change authorize-security-group-ingress --group-id "$1" --ip-permissions "$perms"; }
egress() { perms=$(cat); change authorize-security-group-egress --group-id "$1" --ip-permissions "$perms"; }
STAND_IN=""
if [ -z "$DRY_RUN" ] && [ -n "$CHECK" ]; then
  STAND_IN=$(aws ec2 describe-security-groups --filters "Name=vpc-id,Values=$VPC_ID" "Name=group-name,Values=default" --query 'SecurityGroups[0].GroupId' --output text $AWS_OPTS) || fail "no default group in $VPC_ID"
fi

# No group of these names may exist.
free 'fwshift-addresses'
free 'fwshift-dmz1'
free 'fwshift-webserver'
free 'fwshift-mailserver'
free 'fwshift-internal'
free 'fwshift-admin-pc'
free 'fwshift-external'
free 'fwshift-external-interface'
free 'fwshift-no-rules'

# The groups, each with the private addresses of the network interfaces it is for.
# attach fwshift-addresses: 0.0.0.0-172.16.19.255 172.16.21.0-192.168.9.255 192.168.11.0-203.0.112.255 203.0.113.8-255.255.255.255
G1=$(group 'fwshift-addresses' 'FWShift: for the interfaces of 0.0.0.0-172.16.19.255 172.16.21.0-192.168.9.255 192.168.11.0-203.0.112.255 203.0.113.8-255.255.255.255') || exit 1
# attach fwshift-dmz1: 172.16.20.0-172.16.20.9 172.16.20.11-172.16.20.24 172.16.20.26-172.16.20.255
G2=$(group 'fwshift-dmz1' 'FWShift: for the interfaces of 172.16.20.0-172.16.20.9 172.16.20.11-172.16.20.24 172.16.20.26-172.16.20.255') || exit 1
# attach fwshift-webserver: 172.16.20.10
G3=$(group 'fwshift-webserver' 'FWShift: for the interfaces of 172.16.20.10') || exit 1
# attach fwshift-mailserver: 172.16.20.25
G4=$(group 'fwshift-mailserver' 'FWShift: for the interfaces of 172.16.20.25') || exit 1
# attach fwshift-internal: 192.168.10.0-192.168.10.49 192.168.10.51-192.168.10.255
G5=$(group 'fwshift-internal' 'FWShift: for the interfaces of 192.168.10.0-192.168.10.49 192.168.10.51-192.168.10.255') || exit 1
# attach fwshift-admin-pc: 192.168.10.50
G6=$(group 'fwshift-admin-pc' 'FWShift: for the interfaces of 192.168.10.50') || exit 1
# attach fwshift-external: 203.0.113.0/31 203.0.113.3-203.0.113.7
G7=$(group 'fwshift-external' 'FWShift: for the interfaces of 203.0.113.0/31 203.0.113.3-203.0.113.7') || exit 1
# attach fwshift-external-interface: 203.0.113.2
G8=$(group 'fwshift-external-interface' 'FWShift: for the interfaces of 203.0.113.2') || exit 1
# attach fwshift-no-rules: ::/0
G9=$(group 'fwshift-no-rules' 'FWShift: for the interfaces of ::/0') || exit 1

# Their rules: inbound rules name the sources, outbound rules the destinations.
ingress "$G1" <<'FWSHIFT_JSON'
[{"IpProtocol": "icmp", "FromPort": 8, "ToPort": -1, "IpRanges": [{"CidrIp": "192.168.10.50/32", "Description": "FWShift: rule-13"}]}]
FWSHIFT_JSON
ingress "$G2" <<'FWSHIFT_JSON'
[{"IpProtocol": "tcp", "FromPort": 8000, "ToPort": 8010, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: rule-12"}]}, {"IpProtocol": "icmp", "FromPort": 8, "ToPort": -1, "IpRanges": [{"CidrIp": "192.168.10.50/32", "Description": "FWShift: rule-13"}]}]
FWSHIFT_JSON
egress "$G2" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "203.0.113.0/31", "Description": "FWShift: rule-8"}, {"CidrIp": "203.0.113.3/32", "Description": "FWShift: rule-8"}, {"CidrIp": "203.0.113.4/30", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "tcp", "FromPort": 0, "ToPort": 442, "IpRanges": [{"CidrIp": "203.0.113.2/32", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "tcp", "FromPort": 444, "ToPort": 65535, "IpRanges": [{"CidrIp": "203.0.113.2/32", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "udp", "FromPort": 0, "ToPort": 65535, "IpRanges": [{"CidrIp": "203.0.113.2/32", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "icmp", "FromPort": -1, "ToPort": -1, "IpRanges": [{"CidrIp": "203.0.113.2/32", "Description": "FWShift: rule-8"}]}]
FWSHIFT_JSON
ingress "$G3" <<'FWSHIFT_JSON'
[{"IpProtocol": "tcp", "FromPort": 22, "ToPort": 22, "IpRanges": [{"CidrIp": "192.168.10.50/32", "Description": "FWShift: rule-7"}]}, {"IpProtocol": "tcp", "FromPort": 8000, "ToPort": 8010, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: rule-12"}]}, {"IpProtocol": "icmp", "FromPort": 8, "ToPort": -1, "IpRanges": [{"CidrIp": "192.168.10.50/32", "Description": "FWShift: rule-13"}]}]
FWSHIFT_JSON
egress "$G3" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "203.0.113.0/31", "Description": "FWShift: rule-8"}, {"CidrIp": "203.0.113.3/32", "Description": "FWShift: rule-8"}, {"CidrIp": "203.0.113.4/30", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "tcp", "FromPort": 0, "ToPort": 442, "IpRanges": [{"CidrIp": "203.0.113.2/32", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "tcp", "FromPort": 444, "ToPort": 65535, "IpRanges": [{"CidrIp": "203.0.113.2/32", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "udp", "FromPort": 0, "ToPort": 65535, "IpRanges": [{"CidrIp": "203.0.113.2/32", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "icmp", "FromPort": -1, "ToPort": -1, "IpRanges": [{"CidrIp": "203.0.113.2/32", "Description": "FWShift: rule-8"}]}]
FWSHIFT_JSON
ingress "$G4" <<'FWSHIFT_JSON'
[{"IpProtocol": "tcp", "FromPort": 22, "ToPort": 22, "IpRanges": [{"CidrIp": "192.168.10.50/32", "Description": "FWShift: rule-7"}]}, {"IpProtocol": "tcp", "FromPort": 25, "ToPort": 25, "IpRanges": [{"CidrIp": "203.0.113.0/29", "Description": "FWShift: rule-6"}]}, {"IpProtocol": "tcp", "FromPort": 8000, "ToPort": 8010, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: rule-12"}]}, {"IpProtocol": "icmp", "FromPort": 8, "ToPort": -1, "IpRanges": [{"CidrIp": "192.168.10.50/32", "Description": "FWShift: rule-13"}]}]
FWSHIFT_JSON
egress "$G4" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "203.0.113.0/31", "Description": "FWShift: rule-8"}, {"CidrIp": "203.0.113.3/32", "Description": "FWShift: rule-8"}, {"CidrIp": "203.0.113.4/30", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "tcp", "FromPort": 0, "ToPort": 442, "IpRanges": [{"CidrIp": "203.0.113.2/32", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "tcp", "FromPort": 444, "ToPort": 65535, "IpRanges": [{"CidrIp": "203.0.113.2/32", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "udp", "FromPort": 0, "ToPort": 65535, "IpRanges": [{"CidrIp": "203.0.113.2/32", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "icmp", "FromPort": -1, "ToPort": -1, "IpRanges": [{"CidrIp": "203.0.113.2/32", "Description": "FWShift: rule-8"}]}]
FWSHIFT_JSON
ingress "$G5" <<'FWSHIFT_JSON'
[{"IpProtocol": "icmp", "FromPort": 8, "ToPort": -1, "IpRanges": [{"CidrIp": "192.168.10.50/32", "Description": "FWShift: rule-13"}]}]
FWSHIFT_JSON
egress "$G5" <<'FWSHIFT_JSON'
[{"IpProtocol": "tcp", "FromPort": 21, "ToPort": 21, "IpRanges": [{"CidrIp": "203.0.113.0/29", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "tcp", "FromPort": 80, "ToPort": 80, "IpRanges": [{"CidrIp": "203.0.113.0/29", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "203.0.113.0/29", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "tcp", "FromPort": 8000, "ToPort": 8010, "IpRanges": [{"CidrIp": "172.16.20.0/24", "Description": "FWShift: rule-12"}]}, {"IpProtocol": "udp", "FromPort": 53, "ToPort": 53, "IpRanges": [{"CidrIp": "203.0.113.0/29", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "icmp", "FromPort": 8, "ToPort": -1, "IpRanges": [{"CidrIp": "203.0.113.0/29", "Description": "FWShift: rule-1"}]}]
FWSHIFT_JSON
ingress "$G6" <<'FWSHIFT_JSON'
[{"IpProtocol": "icmp", "FromPort": 8, "ToPort": -1, "IpRanges": [{"CidrIp": "192.168.10.50/32", "Description": "FWShift: rule-13"}]}]
FWSHIFT_JSON
egress "$G6" <<'FWSHIFT_JSON'
[{"IpProtocol": "tcp", "FromPort": 21, "ToPort": 21, "IpRanges": [{"CidrIp": "203.0.113.0/29", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "tcp", "FromPort": 22, "ToPort": 22, "IpRanges": [{"CidrIp": "172.16.20.10/32", "Description": "FWShift: rule-7"}, {"CidrIp": "172.16.20.25/32", "Description": "FWShift: rule-7"}]}, {"IpProtocol": "tcp", "FromPort": 80, "ToPort": 80, "IpRanges": [{"CidrIp": "203.0.113.0/29", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "203.0.113.0/29", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "tcp", "FromPort": 8000, "ToPort": 8010, "IpRanges": [{"CidrIp": "172.16.20.0/24", "Description": "FWShift: rule-12"}]}, {"IpProtocol": "udp", "FromPort": 53, "ToPort": 53, "IpRanges": [{"CidrIp": "203.0.113.0/29", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "icmp", "FromPort": 8, "ToPort": -1, "IpRanges": [{"CidrIp": "0.0.0.0/0", "Description": "FWShift: rule-1, rule-13"}]}]
FWSHIFT_JSON
ingress "$G7" <<'FWSHIFT_JSON'
[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "172.16.20.0/24", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "tcp", "FromPort": 21, "ToPort": 21, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "tcp", "FromPort": 80, "ToPort": 80, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "udp", "FromPort": 53, "ToPort": 53, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "icmp", "FromPort": 8, "ToPort": -1, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: rule-1, rule-13"}]}]
FWSHIFT_JSON
egress "$G7" <<'FWSHIFT_JSON'
[{"IpProtocol": "tcp", "FromPort": 25, "ToPort": 25, "IpRanges": [{"CidrIp": "172.16.20.25/32", "Description": "FWShift: rule-6"}]}]
FWSHIFT_JSON
ingress "$G8" <<'FWSHIFT_JSON'
[{"IpProtocol": "tcp", "FromPort": 0, "ToPort": 442, "IpRanges": [{"CidrIp": "172.16.20.0/24", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "tcp", "FromPort": 21, "ToPort": 21, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "tcp", "FromPort": 80, "ToPort": 80, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "tcp", "FromPort": 443, "ToPort": 443, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "tcp", "FromPort": 444, "ToPort": 65535, "IpRanges": [{"CidrIp": "172.16.20.0/24", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "udp", "FromPort": 0, "ToPort": 65535, "IpRanges": [{"CidrIp": "172.16.20.0/24", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "udp", "FromPort": 53, "ToPort": 53, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: rule-1"}]}, {"IpProtocol": "icmp", "FromPort": -1, "ToPort": -1, "IpRanges": [{"CidrIp": "172.16.20.0/24", "Description": "FWShift: rule-8"}]}, {"IpProtocol": "icmp", "FromPort": 8, "ToPort": -1, "IpRanges": [{"CidrIp": "192.168.10.0/24", "Description": "FWShift: rule-1, rule-13"}]}]
